const url = process.env.URL;
if (!url) throw new Error('Missing URL input');
const resp = await fetch(url);
if (!resp.ok) throw new Error(`HTTP error ${resp.status}`);
globalThis.raw = await resp.text();

const { parseDocument } = await import('htmlparser2');
const { DomUtils } = await import('htmlparser2');
const doc = parseDocument(globalThis.raw);
const text = DomUtils.getText(doc);
if (typeof text !== 'string') throw new Error('Failed to extract text');
globalThis.parsed = text;
